questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
cv3(v) := matrix([v[1]],[v[2]],[v[3]]);
e1: matrix([1],[0],[0]); badm: matrix([q],[1],[2]);
/* Design: dividing a line externally. m > n on five entries (Q beyond B), m < n on five (beyond A). Source: original. */
dlist: [[[3,-4,-3],[7,2,-7],3,1],[[0,5,-4],[-2,4,-6],2,1],[[3,-4,3],[9,-7,12],5,2],[[-5,-5,-5],[-3,-7,-6],4,3],[[4,1,-5],[7,4,-4],3,2],[[0,0,-5],[-2,3,-3],1,2],[[4,-2,-4],[6,0,-10],1,3],[[-1,1,5],[-4,-5,8],2,5],[[2,1,-4],[5,-2,5],1,4],[[-2,-3,-2],[0,-7,0],3,5]];
ix: 1+rand(10);
A: dlist[ix][1]; B: dlist[ix][2]; m: dlist[ix][3]; n: dlist[ix][4];
vA: cv3(A); vB: cv3(B); vAB: vB-vA; fq: m/(m-n);
tQ: vA+fq*vAB; tAQ: fq*vAB;
intl: vA+m/(m+n)*vAB; swq: vA+n/(n-m)*vAB; rtw: (m*vA+n*vB)/(m+n);
wQ: tQ+e1;

feedbackvariables.text:
uu: [ans1[1,1], ans1[2,1], ans1[3,1]]; aq: uu-A; ww: B-A;
crs: [aq[2]*ww[3]-aq[3]*ww[2], aq[3]*ww[1]-aq[1]*ww[3], aq[1]*ww[2]-aq[2]*ww[1]];
onl: is(abs(crs[1])+abs(crs[2])+abs(crs[3]) < 10^-9);
tq: (aq[1]*ww[1]+aq[2]*ww[2]+aq[3]*ww[3])/(ww[1]^2+ww[2]^2+ww[3]^2);
rr: if ratnump(tq) then block([p: abs(tq), q: abs(1-tq), dd, gg], dd: denom(p)*denom(q), gg: gcd(p*dd, q*dd), [p*dd/gg, q*dd/gg]) else [abs(tq), abs(1-tq)];
